import React, { useEffect, useState } from "react";
import { useLocation } from "react-router";
import { Helmet } from "react-helmet-async";
import Navigation from "../Navigation";
import Footer from "../Footer";
import Prism from "prismjs";
import "prismjs/components/prism-bash";
import { CalendarDateRangeIcon, TagIcon } from "@heroicons/react/24/outline";

function Post35() {
  const location = useLocation();
  const themeModeInitial = location?.state?.themeMode
    ? location.state.themeMode
    : "light";
  const [themeMode, setThemeMode] = useState(themeModeInitial);
  const tags = ["kubernetes", "ingress", "nginx", "haproxy"];

  const configurePrismTheme = (themeMode) => {
    let link = document.getElementById("prism-theme");

    if (!link) {
      link = document.createElement("link");
      link.rel = "stylesheet";
      link.id = "prism-theme";
      document.head.appendChild(link);
    }

    link.href =
      themeMode === "dark"
        ? "https://unpkg.com/prismjs/themes/prism-twilight.css"
        : "https://unpkg.com/prismjs/themes/prism.css";
  };

  const toggleThemeMode = () => {
    if (themeMode === "light") {
      setThemeMode("dark");
      configurePrismTheme("dark");
    } else {
      setThemeMode("light");
      configurePrismTheme("light");
    }
  };

  useEffect(() => {
    if (location?.state?.themeMode) {
      setThemeMode(location.state.themeMode);
      configurePrismTheme(location.state.themeMode);
    } else {
      configurePrismTheme("light");
    }
    window.scrollTo(0, 0);
    Prism.hooks.add("before-highlight", function (env) {
      env.code = env.element.innerText;
    });
    Prism.highlightAll();
  }, [location]);

  return (
    <>
      <Helmet>
        <title>NGINX Ingress Controller Migration</title>
        <meta name="description" content="NGINX Ingress Controller Migration" />
        <meta name="keywords" content="kubernetes, ingress, nginx, haproxy" />
        <meta name="author" content="Marco Cella" />
        {/* Open Graph tags for social media */}
        <meta
          property="og:title"
          content="NGINX Ingress Controller Migration"
        />
        <meta
          property="og:description"
          content="NGINX Ingress Controller Migration"
        />
        <meta property="og:type" content="website" />
      </Helmet>

      <div className={themeMode === "dark" ? "dark" : "light"}>
        <Navigation
          themeMode={themeMode}
          onThemeChange={toggleThemeMode}
        ></Navigation>
        <div className="flex flex-col items-center content min-h-[calc(100vh-172px)] dark:bg-slate-custom6">
          <div className="w-11/12 sm:w-11/12 md:w-9/12 lg:w-8/12 xl:w-6/12 2xl:w-4/12 mx-0">
            <div className="mt-16 mb-4 flex justify-items-start content">
              <h1 className="font-semibold text-left text-3xl lg:text-4xl w-full md:w-full dark:text-gray-custom1">
                NGINX Ingress Controller Migration
              </h1>
              <div className="line-break"></div>
              <span className="flex items-center mt-2">
                <CalendarDateRangeIcon className="h-6 w-6 stroke-orange-400 mr-2 text-gray-custom3 dark:text-gray-400" />
                <time className="text-gray-custom2 text-left text-sm lg:text-base w-full md:w-full dark:text-gray-custom4">
                  Jul 26, 2026
                </time>
              </span>
              <div className="line-break"></div>
              <div
                className={
                  themeMode === "dark"
                    ? "dark articleBody"
                    : "light articleBody"
                }
              >
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  The community-led NGINX Ingress Controller was a popular load
                  balancer in Kubernetes networking. However, in March 2026, the
                  project was officially retired and archived by the Kubernetes
                  SIG Network due to maintenance challenges.
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  The Kubernetes SIG Network and the Security Response Committee
                  announced the{" "}
                  <a
                    className="underline"
                    href="https://kubernetes.io/blog/2025/11/11/ingress-nginx-retirement/"
                    target="_blank"
                    rel="noreferrer"
                  >
                    retirement
                  </a>{" "}
                  of the{" "}
                  <a
                    className="underline"
                    href="https://github.com/kubernetes/ingress-nginx"
                    target="_blank"
                    rel="noreferrer"
                  >
                    NGINX Ingress Controller
                  </a>{" "}
                  project in November 2025. Consequently, bug fixes and updates
                  are no longer available as of March 2026.
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  Infrastructure teams should migrate to an alternative Ingress
                  Controller as soon as possible to ensure they are using a
                  solution that is actively maintained and receives critical
                  security patches.
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  In this article, I will walk through migrating from 
                  NGINX Ingress Controller to{" "}<a
                    className="underline"
                    href="https://www.haproxy.com/documentation/kubernetes-ingress/"
                    target="_blank"
                    rel="noreferrer"
                  >
                    HAProxy Ingress Controller
                  </a>{" "}. Although Kubernetes now recommends the{" "}<a
                    className="underline"
                    href="https://kubernetes.io/docs/concepts/services-networking/gateway/"
                    target="_blank"
                    rel="noreferrer"
                  >
                    Gateway API
                  </a>{" "}
                  because the core{" "}
                  <a
                    className="underline"
                    href="https://kubernetes.io/docs/concepts/services-networking/ingress-controllers/"
                    target="_blank"
                    rel="noreferrer"
                  >
                    Ingress API
                  </a>{" "}is in maintenance mode, many third-party Ingress 
                  controllers remain actively maintained and widely used.
                </p>
                <p className="font-semibold mt-4 text-left text-2xl lg:text-3xl prose dark:text-gray-custom1 dark:prose-invert w-full">
                  Ingress API
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  The Kubernetes documentation defines an Ingress resource as a
                  collection of rules that allow inbound connections to reach
                  cluster Services. A core feature of the Ingress API is its
                  support for multiple Ingress controllers running
                  simultaneously within a single cluster.
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  This multi-controller property allows you to create two
                  separate Ingress resources, one for NGINX and one for HAProxy,
                  that both point to the same Kubernetes service.
                </p>
                <p className="font-semibold mt-4 text-left text-2xl lg:text-3xl prose dark:text-gray-custom1 dark:prose-invert w-full">
                  Project
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  The following repository contains a Terraform project to
                  deploy an Azure Kubernetes Service (AKS) cluster, along with
                  the NGINX and HAProxy Ingress Controllers and a sample web
                  application.
                  <br />
                  <a
                    className="underline"
                    href="https://github.com/sitMCella/nginx-ingress-controller-migration"
                    target="_blank"
                    rel="noreferrer"
                  >
                    sitMCella/nginx-ingress-controller-migration
                  </a>
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  Initially, the web application Ingress resources are
                  configured to use the NGINX Ingress class. One Azure
                  Application Gateway (AGW) connects to the Load Balancer
                  associated with the AKS cluster, routing HTTP traffic to the
                  NGINX Ingress Controller. The AGW backend pool is configured
                  with the IP address of the NGINX Ingress Controller Kubernetes
                  Service.
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  The project uses a simplified configuration for demonstration
                  purposes:
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  <ul>
                    <li>
                      The AKS cluster is public and exposes services via an
                      External Load Balancer.
                    </li>
                    <li>
                      The Ingress resources are not configured with TLS
                      certificates (HTTP only).
                    </li>
                    <li>
                      The application is accessed directly via IP address rather
                      than a custom domain name.
                    </li>
                  </ul>
                </p>
                <p className="font-semibold mt-4 text-left text-2xl lg:text-3xl prose dark:text-gray-custom1 dark:prose-invert w-full">
                  Migration
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  The migration to HAProxy Ingress Controller is designed to
                  ensure zero downtime for applications running in the AKS
                  cluster while minimizing the operational overhead for the
                  DevOps and application teams.
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  The following are the steps to follow:
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  <ul>
                    <li>
                      Deploy the HAProxy Ingress Controller into the AKS
                      cluster.
                    </li>
                    <li>
                      Define the new Ingress resources configured with the
                      HAProxy Ingress class. Migrate all the Ingress resource
                      annotations and the configuration to HAProxy.
                    </li>
                    <li>
                      Provision a secondary Azure Application Gateway (AGW) to
                      serve as the new entry point.
                    </li>
                    <li>
                      Replicate the configuration (listeners, rules, and backend
                      settings) from the original AGW to the new AGW instance.
                    </li>
                    <li>
                      Configure the backend pool of the new AGW to target the IP
                      address of the HAProxy Ingress Controller Kubernetes
                      Service.
                    </li>
                    <li>
                      Update the DNS records of the application endpoints to
                      point to the Public IP of the new AGW.
                    </li>
                    <li>Delete the initial AGW.</li>
                    <li>
                      Decommission the NGINX Ingress Controller from the AKS
                      cluster.
                    </li>
                  </ul>
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  The precise migration of the Ingress resources is the most
                  critical phase of this transition. While the core routing
                  rules (hosts and paths) remain the same, NGINX specific
                  annotations are not compatible with the HAProxy Ingress
                  Controller and must be manually translated.
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  Most teams use annotations for advanced traffic management.
                  When migrating, you must find the HAProxy equivalent for every{" "}
                  <i>nginx.ingress.kubernetes.io</i> tag used in your current 
                  YAML. For a complete list of supported options, refer to 
                  the HAProxy Ingress{" "}<a
                    className="underline"
                    href="https://www.haproxy.com/documentation/kubernetes-ingress/community/configuration-reference/ingress/"
                    target="_blank"
                    rel="noreferrer"
                  >
                    Configuration Reference
                  </a>.
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  Provisioning a new Azure Application Gateway ensures that the
                  application remains reachable throughout the transition,
                  allowing for a controlled cutover at the DNS level.
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  An alternative approach involves creating a new backend pool
                  within the existing Azure Application Gateway and
                  reassociating the listeners with this new backend pool.
                  However, this procedure may cause a brief service interruption
                  during the reconfiguration. Therefore, the dual Application
                  Gateway approach is recommended for mission-critical endpoints
                  that require continuous availability.
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  By leveraging Azure Traffic Manager or Azure Front Door, you
                  can additionally implement weighted traffic splitting between
                  the two Application Gateways. This enables a canary migration,
                  allowing you to validate the HAProxy controller with a small
                  percentage of live traffic before a full cutover.
                </p>
              </div>
            </div>
            <div className="mt-8 flex items-center text-left">
              <TagIcon className="h-5 w-5 stroke-orange-400 mr-1 text-gray-custom3 dark:text-gray-400" />
              {tags.map((item, index) => (
                <span
                  key={`tag-${index}`}
                  className="m-1 px-1.5 py-0.5 border rounded border-gray-custom3 text-gray-custom2 dark:border-gray-400 dark:text-gray-custom4 text-xs lg:text-sm font-medium text-left text-base prose"
                >
                  {item}
                </span>
              ))}
            </div>
          </div>
          <div className="mb-16"></div>
          <div></div>
        </div>
        <Footer></Footer>
      </div>
    </>
  );
}

export default Post35;
