import React, { useEffect, useState } from "react";
import { useLocation } from "react-router";
import { Helmet } from "react-helmet-async";
import Navigation from "../Navigation";
import Footer from "../Footer";
import Prism from "prismjs";
import "prismjs/components/prism-bash";
import { CalendarDateRangeIcon, TagIcon } from "@heroicons/react/24/outline";

function Post29() {
  const location = useLocation();
  const themeModeInitial = location?.state?.themeMode
    ? location.state.themeMode
    : "light";
  const [themeMode, setThemeMode] = useState(themeModeInitial);
  const tags = ["azure", "firewall"];

  const configurePrismTheme = (themeMode) => {
    let link = document.getElementById("prism-theme");

    if (!link) {
      link = document.createElement("link");
      link.rel = "stylesheet";
      link.id = "prism-theme";
      document.head.appendChild(link);
    }

    link.href =
      themeMode === "dark"
        ? "https://unpkg.com/prismjs/themes/prism-twilight.css"
        : "https://unpkg.com/prismjs/themes/prism.css";
  };

  const toggleThemeMode = () => {
    if (themeMode === "light") {
      setThemeMode("dark");
      configurePrismTheme("dark");
    } else {
      setThemeMode("light");
      configurePrismTheme("light");
    }
  };

  useEffect(() => {
    if (location?.state?.themeMode) {
      setThemeMode(location.state.themeMode);
      configurePrismTheme(location.state.themeMode);
    } else {
      configurePrismTheme("light");
    }
    window.scrollTo(0, 0);
    Prism.hooks.add("before-highlight", function (env) {
      env.code = env.element.innerText;
    });
    Prism.highlightAll();
  }, [location]);

  return (
    <>
      <Helmet>
        <title>Azure Firewall Policy Update Automation</title>
        <meta
          name="description"
          content="Azure Firewall Policy Update Automation"
        />
        <meta name="keywords" content="azure, firewall" />
        <meta name="author" content="Marco Cella" />
        {/* Open Graph tags for social media */}
        <meta
          property="og:title"
          content="Azure Firewall Policy Update Automation"
        />
        <meta
          property="og:description"
          content="Azure Firewall Policy Update Automation"
        />
        <meta property="og:type" content="website" />
      </Helmet>

      <div className={themeMode === "dark" ? "dark" : "light"}>
        <Navigation
          themeMode={themeMode}
          onThemeChange={toggleThemeMode}
        ></Navigation>
        <div className="flex flex-col items-center content min-h-[calc(100vh-172px)] dark:bg-slate-custom6">
          <div className="w-11/12 sm:w-11/12 md:w-9/12 lg:w-8/12 xl:w-6/12 2xl:w-4/12 mx-0">
            <div className="mt-16 mb-4 flex justify-items-start content">
              <h1 className="font-semibold text-left text-3xl lg:text-4xl w-full md:w-full dark:text-gray-custom1">
                Azure Firewall Policy Update Automation
              </h1>
              <div className="line-break"></div>
              <span className="flex items-center mt-2">
                <CalendarDateRangeIcon className="h-6 w-6 stroke-orange-400 mr-2 text-gray-custom3 dark:text-gray-400" />
                <time className="text-gray-custom2 text-left text-sm lg:text-base w-full md:w-full dark:text-gray-custom4">
                  Dec 7, 2025
                </time>
              </span>
              <div className="line-break"></div>
              <div
                className={
                  themeMode === "dark"
                    ? "dark articleBody"
                    : "light articleBody"
                }
              >
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  Service providers and cloud vendors maintain comprehensive
                  lists of IP address ranges that correspond to their services
                  or SaaS offerings. These lists are typically published and
                  updated regularly to help customers configure firewalls,
                  access controls, and network routing rules.
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  By referencing these IP address ranges, organizations can
                  securely allow or restrict traffic to trusted services, ensure
                  compliance with network policies, and maintain uninterrupted
                  connectivity as the cloud infrastructure evolve.
                </p>
                <p className="font-semibold mt-4 text-left text-2xl lg:text-3xl prose dark:text-gray-custom1 dark:prose-invert w-full">
                  Scenario
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  One or more applications in the cloud environment might
                  require to communicate with third party services, so you need
                  to create firewall rules to allow either inbound or outbound
                  traffic to the external services. Because these IP address
                  ranges are dynamic, firewall rules defined in an Azure
                  Firewall Policy must be updated whenever the service provider
                  changes the IP address ranges.
                </p>
                <p className="font-semibold mt-4 text-left text-2xl lg:text-3xl prose dark:text-gray-custom1 dark:prose-invert w-full">
                  Project
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  The following repository contains a tool that automatically
                  updates Azure Firewall Policy rules based on IP address ranges
                  published in one external repository:
                  <br />
                  <a
                    className="underline"
                    href="https://github.com/sitMCella/azure-firewall-rules-automation"
                    target="_blank"
                    rel="noreferrer"
                  >
                    sitMCella/azure-firewall-rules-automation
                  </a>
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  The automation tool is a Python script hosted in one Azure
                  Functions App. The function extracts the IP address ranges for
                  a specific service name from a remote published file, and
                  creates a Pull Request in the GitHub repository containing the
                  Terraform code of the Azure Firewall Policy. The Firewall
                  rules whose names match a specified regex pattern are
                  automatically updated with the latest published IP address
                  ranges.
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  The solution requires to provide the name, the owner, and a
                  PAT token of the GitHub repository that contains the Terraform
                  code of the Azure Firewall Policy resource.
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  The script makes use of a GitHub PAT token to create a Pull
                  Request in the GitHub repository with the updated IP Address
                  ranges of the firewall rules. The PAT token must be a
                  fine-grained token with Read access to metadata, and Read and
                  Write access to code (Contents), pull requests, and workflows.
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  The automation solution has been configured to extract the IP
                  address ranges of the service with name
                  "AzureMachineLearning.WestEurope" from the document published
                  by Microsoft in the page "{" "}
                  <a
                    className="underline"
                    href="https://www.microsoft.com/en-us/download/details.aspx?id=56519"
                    target="_blank"
                    rel="noreferrer"
                  >
                    Azure IP Ranges and Service Tags for the Public Cloud
                  </a>
                  ".
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  The tool can be adapted for use in a variety of contexts. For
                  example it could be used to automatically whitelist traffic to
                  or from a third-party partner service, ensuring secure and
                  seamless communication between trusted systems.
                </p>
              </div>
            </div>
            <div className="mt-8 flex items-center text-left">
              <TagIcon className="h-5 w-5 stroke-orange-400 mr-1 text-gray-custom3 dark:text-gray-400" />
              {tags.map((item, index) => (
                <span
                  key={`tag-${index}`}
                  className="m-1 px-1.5 py-0.5 border rounded border-gray-custom3 text-gray-custom2 dark:border-gray-400 dark:text-gray-custom4 text-xs lg:text-sm font-medium text-left text-base prose"
                >
                  {item}
                </span>
              ))}
            </div>
          </div>
          <div className="mb-16"></div>
          <div></div>
        </div>
        <Footer></Footer>
      </div>
    </>
  );
}

export default Post29;
