import React, { useEffect, useState } from "react";
import { useLocation } from "react-router";
import { Helmet } from "react-helmet-async";
import Navigation from "../Navigation";
import Footer from "../Footer";
import Prism from "prismjs";
import "prismjs/components/prism-bash";
import { CalendarDateRangeIcon, TagIcon } from "@heroicons/react/24/outline";

function Post30() {
  const location = useLocation();
  const themeModeInitial = location?.state?.themeMode
    ? location.state.themeMode
    : "light";
  const [themeMode, setThemeMode] = useState(themeModeInitial);
  const tags = ["toggl", "trello"];

  const configurePrismTheme = (themeMode) => {
    let link = document.getElementById("prism-theme");

    if (!link) {
      link = document.createElement("link");
      link.rel = "stylesheet";
      link.id = "prism-theme";
      document.head.appendChild(link);
    }

    link.href =
      themeMode === "dark"
        ? "https://unpkg.com/prismjs/themes/prism-twilight.css"
        : "https://unpkg.com/prismjs/themes/prism.css";
  };

  const toggleThemeMode = () => {
    if (themeMode === "light") {
      setThemeMode("dark");
      configurePrismTheme("dark");
    } else {
      setThemeMode("light");
      configurePrismTheme("light");
    }
  };

  useEffect(() => {
    if (location?.state?.themeMode) {
      setThemeMode(location.state.themeMode);
      configurePrismTheme(location.state.themeMode);
    } else {
      configurePrismTheme("light");
    }
    window.scrollTo(0, 0);
    Prism.hooks.add("before-highlight", function (env) {
      env.code = env.element.innerText;
    });
    Prism.highlightAll();
  }, [location]);

  return (
    <>
      <Helmet>
        <title>Toggl and Trello KPI Dashboard</title>
        <meta name="description" content="Toggl and Trello KPI Dashboard" />
        <meta name="keywords" content="toggl, trello" />
        <meta name="author" content="Marco Cella" />
        {/* Open Graph tags for social media */}
        <meta property="og:title" content="Toggl and Trello KPI Dashboard" />
        <meta
          property="og:description"
          content="Toggl and Trello KPI Dashboard"
        />
        <meta property="og:type" content="website" />
      </Helmet>

      <div className={themeMode === "dark" ? "dark" : "light"}>
        <Navigation
          themeMode={themeMode}
          onThemeChange={toggleThemeMode}
        ></Navigation>
        <div className="flex flex-col items-center content min-h-[calc(100vh-172px)] dark:bg-slate-custom6">
          <div className="w-11/12 sm:w-11/12 md:w-9/12 lg:w-8/12 xl:w-6/12 2xl:w-4/12 mx-0">
            <div className="mt-16 mb-4 flex justify-items-start content">
              <h1 className="font-semibold text-left text-3xl lg:text-4xl w-full md:w-full dark:text-gray-custom1">
                Toggl and Trello KPI Dashboard
              </h1>
              <div className="line-break"></div>
              <span className="flex items-center mt-2">
                <CalendarDateRangeIcon className="h-6 w-6 stroke-orange-400 mr-2 text-gray-custom3 dark:text-gray-400" />
                <time className="text-gray-custom2 text-left text-sm lg:text-base w-full md:w-full dark:text-gray-custom4">
                  Jan 25, 2026
                </time>
              </span>
              <div className="line-break"></div>
              <div
                className={
                  themeMode === "dark"
                    ? "dark articleBody"
                    : "light articleBody"
                }
              >
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  Toggl Track and Trello are productivity tools commonly used
                  for project and work management. In a typical scenario, team
                  members collaborate on features within a single product. In
                  some cases, however, it is more effective to create a separate
                  project for each customer, especially when the products or
                  requirements differ significantly.
                </p>
                <p className="font-semibold mt-4 text-left text-2xl lg:text-3xl prose dark:text-gray-custom1 dark:prose-invert w-full">
                  Toggl Track
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  <a
                    className="underline"
                    href="https://track.toggl.com"
                    target="_blank"
                    rel="noreferrer"
                  >
                    Toggl Track
                  </a>{" "}
                  is a time tracking and productivity tool used by teams to
                  measure how time is spent on tasks and projects. It allows
                  users to create projects, assign clients and team members to
                  the projects, and organize time entries using tags.
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  Toggl Track also generates reports that help analyze how time
                  is spent. Summary reports provide a high level view of how
                  tracked time is distributed across projects and weeks, while
                  detailed reports offer a more granular breakdown of individual
                  time entries.
                </p>
                <p className="font-semibold mt-4 text-left text-2xl lg:text-3xl prose dark:text-gray-custom1 dark:prose-invert w-full">
                  Trello
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  <a
                    className="underline"
                    href="https://trello.com"
                    target="_blank"
                    rel="noreferrer"
                  >
                    Trello
                  </a>{" "}
                  is a visual project management and collaboration tool based on
                  Kanban boards. It is used to manage projects, tasks, roadmaps,
                  and backlogs, and to support effective team collaboration.
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  Each Trello board can be customized with workflow stages (such
                  as To-do, Doing, and Done), and the cards on the board
                  represent individual tasks, complete with descriptions,
                  checklists, labels, and due dates.
                </p>
                <p className="font-semibold mt-4 text-left text-2xl lg:text-3xl prose dark:text-gray-custom1 dark:prose-invert w-full">
                  Project
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  The following repository contains a tool that generates a
                  Grafana dashboard to visualize key performance indicators
                  (KPIs) based on data from Toggl and Trello:
                  <br />
                  <a
                    className="underline"
                    href="https://github.com/sitMCella/toggl-trello-kpi"
                    target="_blank"
                    rel="noreferrer"
                  >
                    sitMCella/toggl-trello-kpi
                  </a>
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  The Grafana dashboard uses a preconfigured layout, with charts
                  connected to a PostgreSQL data source to retrieve and
                  visualize the data.
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  A simple Golang command-line tool is used to download data
                  from Toggl Track and Trello via their REST APIs. To retrieve
                  data from Toggl Track, the user must provide an API token and
                  a workspace ID. To retrieve data from Trello, the user must
                  provide the application key, the API token, and the board ID.
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  The application requires structuring the labels applied to
                  Trello cards into the following categories: project name,
                  customer name, team name, and task type (e.g., design,
                  implementation, incident). The application then maps these
                  labels to the visualizations, using the colors assigned to
                  each label for consistent representation.
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  The application does not assume any direct integration between
                  Toggl and Trello. As a result, the association between Toggl
                  time entries and Trello cards must be established manually.
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  The Grafana dashboard is designed to visualize the KPIs for a
                  single team member, providing insights into the time
                  allocation across tasks and projects, and the progress over
                  time. The visualization can help identify project
                  criticalities, such as blockers, incident rates, and context
                  switching for the team member.
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  Creating a Grafana dashboard has the advantage of allowing
                  customization of the visualizations, as well as extending and
                  modifying the provided KPIs, enabling teams to tailor the
                  metrics to their specific workflows, track additional
                  performance indicators, and adapt the dashboard as project
                  requirements evolve.
                </p>
              </div>
            </div>
            <div className="mt-8 flex items-center text-left">
              <TagIcon className="h-5 w-5 stroke-orange-400 mr-1 text-gray-custom3 dark:text-gray-400" />
              {tags.map((item, index) => (
                <span
                  key={`tag-${index}`}
                  className="m-1 px-1.5 py-0.5 border rounded border-gray-custom3 text-gray-custom2 dark:border-gray-400 dark:text-gray-custom4 text-xs lg:text-sm font-medium text-left text-base prose"
                >
                  {item}
                </span>
              ))}
            </div>
          </div>
          <div className="mb-16"></div>
          <div></div>
        </div>
        <Footer></Footer>
      </div>
    </>
  );
}

export default Post30;
