import React, { useEffect, useState } from "react";
import { Link, useLocation } from "react-router";
import { Helmet } from "react-helmet-async";
import Navigation from "../Navigation";
import Footer from "../Footer";
import Prism from "prismjs";
import "prismjs/components/prism-bash";
import { CalendarDateRangeIcon, TagIcon } from "@heroicons/react/24/outline";

function Post31() {
  const location = useLocation();
  const themeModeInitial = location?.state?.themeMode
    ? location.state.themeMode
    : "light";
  const [themeMode, setThemeMode] = useState(themeModeInitial);
  const tags = ["webflux", "spring"];

  const configurePrismTheme = (themeMode) => {
    let link = document.getElementById("prism-theme");

    if (!link) {
      link = document.createElement("link");
      link.rel = "stylesheet";
      link.id = "prism-theme";
      document.head.appendChild(link);
    }

    link.href =
      themeMode === "dark"
        ? "https://unpkg.com/prismjs/themes/prism-twilight.css"
        : "https://unpkg.com/prismjs/themes/prism.css";
  };

  const toggleThemeMode = () => {
    if (themeMode === "light") {
      setThemeMode("dark");
      configurePrismTheme("dark");
    } else {
      setThemeMode("light");
      configurePrismTheme("light");
    }
  };

  useEffect(() => {
    if (location?.state?.themeMode) {
      setThemeMode(location.state.themeMode);
      configurePrismTheme(location.state.themeMode);
    } else {
      configurePrismTheme("light");
    }
    window.scrollTo(0, 0);
    Prism.hooks.add("before-highlight", function (env) {
      env.code = env.element.innerText;
    });
    Prism.highlightAll();
  }, [location]);

  return (
    <>
      <Helmet>
        <title>Reactive Streams with Spring WebFlux</title>
        <meta
          name="description"
          content="Reactive Streams with Spring WebFlux"
        />
        <meta name="keywords" content="webflux, spring" />
        <meta name="author" content="Marco Cella" />
        {/* Open Graph tags for social media */}
        <meta
          property="og:title"
          content="Reactive Streams with Spring WebFlux"
        />
        <meta
          property="og:description"
          content="Reactive Streams with Spring WebFlux"
        />
        <meta property="og:type" content="website" />
      </Helmet>

      <div className={themeMode === "dark" ? "dark" : "light"}>
        <Navigation
          themeMode={themeMode}
          onThemeChange={toggleThemeMode}
        ></Navigation>
        <div className="flex flex-col items-center content min-h-[calc(100vh-172px)] dark:bg-slate-custom6">
          <div className="w-11/12 sm:w-11/12 md:w-9/12 lg:w-8/12 xl:w-6/12 2xl:w-4/12 mx-0">
            <div className="mt-16 mb-4 flex justify-items-start content">
              <h1 className="font-semibold text-left text-3xl lg:text-4xl w-full md:w-full dark:text-gray-custom1">
                Reactive Streams with Spring WebFlux
              </h1>
              <div className="line-break"></div>
              <span className="flex items-center mt-2">
                <CalendarDateRangeIcon className="h-6 w-6 stroke-orange-400 mr-2 text-gray-custom3 dark:text-gray-400" />
                <time className="text-gray-custom2 text-left text-sm lg:text-base w-full md:w-full dark:text-gray-custom4">
                  Feb 21, 2026
                </time>
              </span>
              <div className="line-break"></div>
              <div
                className={
                  themeMode === "dark"
                    ? "dark articleBody"
                    : "light articleBody"
                }
              >
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  Asynchronous processing helps deliver real-time,
                  data-intensive applications and improves scalability, and
                  responsiveness, while enabling efficient resource usage,
                  backpressure handling, and non-blocking behavior.
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  The{" "}
                  <a
                    className="underline"
                    href="https://reactivemanifesto.org"
                    target="_blank"
                    rel="noreferrer"
                  >
                    Reactive Manifesto
                  </a>{" "}
                  describes Reactive Systems as responsive, resilient, elastic,
                  and message-driven. A Reactive System is composable, and all
                  of its components should adhere to these reactive principles,
                  enabling applications to handle high loads gracefully, recover
                  from failures automatically, scale efficiently under varying
                  demand, and communicate reliably through asynchronous
                  message-passing.
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  The Reactive Streams initiative is a specification and
                  standard for asynchronous stream processing with non-blocking
                  backpressure in the JVM ecosystem. It was created to address
                  the challenges of building reactive, high-throughput, and
                  resilient applications that handle large volumes of data.
                </p>
                <p className="font-semibold mt-4 text-left text-2xl lg:text-3xl prose dark:text-gray-custom1 dark:prose-invert w-full">
                  Spring WebFlux
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  <a
                    className="underline"
                    href="https://docs.spring.io/spring-framework/reference/web/webflux.html"
                    target="_blank"
                    rel="noreferrer"
                  >
                    Spring WebFlux
                  </a>{" "}
                  is a reactive, non-blocking web framework in the Spring
                  ecosystem. It fully supports non-blocking I/O, provides
                  backpressure via the Reactive Streams specification, and can
                  run on servers such as Netty or Servlet 3.1+ containers.
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  The original Spring Web MVC framework was built on the Servlet
                  API and designed to run in servlet containers. It is a
                  synchronous, request-driven framework that relies on blocking
                  I/O operations. Each incoming HTTP request is handled by a
                  dedicated thread from the servlet container thread pool.
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  Spring WebFlux uses Netty as its default network application
                  framework. Netty is designed to be non-blocking from the
                  ground up and uses EventLoop to handle non-blocking I/O, built
                  on top of Java NIO.
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  Servlet 3.1+ containers such as Tomcat and Jetty can support
                  reactive frameworks like Spring WebFlux thanks to the
                  asynchronous and non-blocking extensions introduced in the
                  Servlet 3.1 specification.
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  <a
                    className="underline"
                    href="https://projectreactor.io"
                    target="_blank"
                    rel="noreferrer"
                  >
                    Reactor
                  </a>{" "}
                  is the reactive library of choice for Spring WebFlux. It
                  provides the <code>Mono</code> and <code>Flux</code> API types
                  for working with asynchronous data sequences through a rich
                  set of operators. Both <i>Mono</i> and <i>Flux</i> implement
                  the Reactive Streams specification
                  <code>Publisher&lt;T&gt;</code>. A <i>Mono</i> emits at most
                  one item, while a <i>Flux</i> represents an asynchronous
                  sequence that can emit zero to many items.
                </p>
                <p className="font-semibold mt-4 text-left text-2xl lg:text-3xl prose dark:text-gray-custom1 dark:prose-invert w-full">
                  Project
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  I implemented a simple reactive backend for the Radar
                  application using Spring WebFlux:
                  <br />
                  <a
                    className="underline"
                    href="https://github.com/sitMCella/radar"
                    target="_blank"
                    rel="noreferrer"
                  >
                    sitMCella/radar
                  </a>
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  The following Gradle dependency is sufficient to set up a
                  Spring Boot 3 application with Spring WebFlux. The&nbsp;
                  <code>spring-boot-starter-webflux</code> dependency includes
                  Spring WebFlux, Project Reactor, Netty, and the Spring
                  Boot&nbsp;<code>auto-configuration</code> for WebFlux.
                </p>
                <pre className="mt-4 text-left h-68 w-full">
                  <code className="language-java">
                    dependencies &#123;
                    <br />
                    &nbsp;&nbsp;implementation
                    'org.springframework.boot:spring-boot-starter-webflux'
                    <br />
                    &#125;
                  </code>
                </pre>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  To create a reactive application, all components must be
                  reactive. For example, the database access must use a reactive
                  library, and external service calls should be handled
                  asynchronously. This ensures that the application remains
                  non-blocking throughout its execution, allowing it to handle
                  high concurrency, stream data efficiently, and remain
                  responsive under heavy load.
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  The application uses a PostgreSQL database, so reactive
                  libraries are required for non-blocking database interactions.
                  The&nbsp;<code>spring-boot-starter-data-r2dbc</code> library
                  provides R2DBC support within Spring, while&nbsp;
                  <code>r2dbc-postgresql</code> is the R2DBC driver specifically
                  for PostgreSQL.
                </p>
                <pre className="mt-4 text-left h-68 w-full">
                  <code className="language-java">
                    dependencies &#123;
                    <br />
                    &nbsp;&nbsp;implementation
                    'org.springframework.boot:spring-boot-starter-data-r2dbc'
                    <br />
                    &nbsp;&nbsp;implementation
                    'org.postgresql:r2dbc-postgresql:1.0.7.RELEASE'
                    <br />
                    &#125;
                  </code>
                </pre>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  Spring WebFlux uses the same <i>@Controller</i> annotation as
                  Spring MVC. The <i>@RequestMapping</i> annotation is used to
                  map HTTP requests to controller methods.
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  The controller "SignalController" defines an endpoint that
                  returns a <code>Flux&lt;Signal&gt;</code> and emits
                  Server-Sent Events (SSE) to the client, with the content type
                  set to <code>text/event-stream</code>.
                </p>
                <pre className="mt-4 text-left h-96 w-full">
                  <code className="language-java">
                    import de.mcella.spring.radarreactive.signal.dto.Signal;
                    <br />
                    import org.springframework.http.*;
                    <br />
                    import org.springframework.web.bind.annotation.*;
                    <br />
                    import reactor.core.publisher.Flux;
                    <br />
                    <br />
                    @RestController
                    <br />
                    @RequestMapping("/api/signals")
                    <br />
                    public class SignalController &#123;
                    <br />
                    &nbsp;&nbsp;private final SignalService signalService;
                    <br />
                    <br />
                    &nbsp;&nbsp;SignalController(SignalService signalService)
                    &#123;
                    <br />
                    &nbsp;&nbsp;&nbsp;&nbsp;this.signalService = signalService;
                    <br />
                    &nbsp;&nbsp;&#125;
                    <br />
                    <br />
                    &nbsp;&nbsp;@GetMapping(produces =
                    MediaType.TEXT_EVENT_STREAM_VALUE)
                    <br />
                    &nbsp;&nbsp;@ResponseStatus(HttpStatus.OK)
                    <br />
                    &nbsp;&nbsp;public Flux&lt;Signal&gt; streamSignals() &#123;
                    <br />
                    &nbsp;&nbsp;&nbsp;&nbsp;return
                    this.signalService.streamSignals();
                    <br />
                    &nbsp;&nbsp;&#125;
                    <br />
                    &#125;
                  </code>
                </pre>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  To start a reactive pipeline and request data, a subscriber
                  must subscribe to a <i>Mono</i> or <i>Flux</i> publisher.
                  Reactor follows the Reactive Streams protocol, responding to
                  the onSubscribe, onNext, onComplete, and onError signals.
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  The service "SignalService" is configured to subscribe to the
                  PostgreSQL event stream.
                </p>
                <pre className="mt-4 text-left h-96 w-full">
                  <code className="language-java">
                    import com.fasterxml.jackson.databind.ObjectMapper;
                    <br />
                    import io.r2dbc.postgresql.PostgresqlConnectionFactory;
                    <br />
                    import io.r2dbc.postgresql.api.*;
                    <br />
                    import jakarta.annotation.*;
                    <br />
                    import
                    org.springframework.data.r2dbc.repository.config.EnableR2dbcRepositories;
                    <br />
                    import org.springframework.stereotype.Service;
                    <br />
                    import reactor.core.publisher.*;
                    <br />
                    <br />
                    @Service
                    <br />
                    @EnableR2dbcRepositories(considerNestedRepositories = true)
                    <br />
                    public class SignalService &#123;
                    <br />
                    <br />
                    &nbsp;&nbsp;private final PostgresqlConnection connection;
                    <br />
                    <br />
                    &nbsp;&nbsp;private final ObjectMapper objectMapper;
                    <br />
                    <br />
                    &nbsp;&nbsp;SignalService(PostgresqlConnectionFactory
                    connectionFactory, ObjectMapper objectMapper) &#123;
                    <br />
                    &nbsp;&nbsp;&nbsp;&nbsp;this.connection =
                    <br />
                    &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Mono.from(connectionFactory.create()).cast(PostgresqlConnection.class).block();
                    <br />
                    &nbsp;&nbsp;&nbsp;&nbsp;this.objectMapper = objectMapper;
                    <br />
                    &nbsp;&nbsp;&#125;
                    <br />
                    <br />
                    &nbsp;&nbsp;@PostConstruct
                    <br />
                    &nbsp;&nbsp;private void postConstruct() &#123;
                    <br />
                    &nbsp;&nbsp;&nbsp;&nbsp;connection
                    <br />
                    &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;.createStatement("LISTEN
                    signals_notification")
                    <br />
                    &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;.execute()
                    <br />
                    &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;.flatMap(PostgresqlResult::getRowsUpdated)
                    <br />
                    &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;.subscribe();
                    <br />
                    &nbsp;&nbsp;&#125;
                    <br />
                    <br />
                    &nbsp;&nbsp;@PreDestroy
                    <br />
                    &nbsp;&nbsp;private void preDestroy() &#123;
                    <br />
                    &nbsp;&nbsp;&nbsp;&nbsp;connection.close().subscribe();
                    <br />
                    &nbsp;&nbsp;&#125;
                    <br />
                    &#125;
                  </code>
                </pre>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  The service contains the following method to listen for
                  PostgreSQL events from a PostgresqlConnection, and generates a{" "}
                  <code>Flux&lt;Signal&gt;</code>.
                </p>
                <pre className="mt-4 text-left h-68 w-full">
                  <code className="language-java">
                    public Flux&lt;Signal&gt; streamSignals() &#123;
                    <br />
                    &nbsp;&nbsp;return connection
                    <br />
                    &nbsp;&nbsp;&nbsp;&nbsp;.getNotifications()
                    <br />
                    &nbsp;&nbsp;&nbsp;&nbsp;.onBackpressureBuffer(1000, dropped
                    -&gt; logger.warn("Dropped notification: " + dropped))
                    <br />
                    &nbsp;&nbsp;&nbsp;&nbsp;.map(notification -&gt; &#123;
                    <br />
                    &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;try &#123;
                    <br />
                    &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;return
                    objectMapper.readValue(notification.getParameter(),
                    Signal.class);
                    <br />
                    &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&#125; catch
                    (JsonProcessingException e) &#123;
                    <br />
                    &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;logger.error("Cannot
                    send signal", e);
                    <br />
                    &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&#125;
                    <br />
                    &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;return null;
                    <br />
                    &nbsp;&nbsp;&nbsp;&nbsp;&#125;);
                    <br />
                    &#125;
                  </code>
                </pre>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  In Spring WebFlux, the backpressure buffer operator
                  temporarily stores incoming items in a bounded or unbounded
                  queue until the subscriber is ready to process them.
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  Several considerations must be addressed when working with
                  reactive frameworks, particularly the shift in programming
                  model compared to imperative programming, the design of the
                  application and its infrastructure, and the choice of
                  application dependencies. A reactive architecture is
                  especially beneficial for applications that require real-time
                  updates, high-throughput event processing, or scalable
                  microservices.
                </p>
                <p className="font-semibold mt-4 text-left text-2xl lg:text-3xl prose dark:text-gray-custom1 dark:prose-invert w-full">
                  Related Posts
                </p>
                <p className="mt-4 text-left text-base lg:text-lg prose dark:text-gray-custom1 dark:prose-invert w-full">
                  <ul>
                    <li>
                      <Link
                        to="/post_20250525"
                        state={{ themeMode: themeMode }}
                      >
                        PostgreSQL Triggers and notify/listen
                      </Link>
                    </li>
                  </ul>
                </p>
              </div>
            </div>
            <div className="mt-8 flex items-center text-left">
              <TagIcon className="h-5 w-5 stroke-orange-400 mr-1 text-gray-custom3 dark:text-gray-400" />
              {tags.map((item, index) => (
                <span
                  key={`tag-${index}`}
                  className="m-1 px-1.5 py-0.5 border rounded border-gray-custom3 text-gray-custom2 dark:border-gray-400 dark:text-gray-custom4 text-xs lg:text-sm font-medium text-left text-base prose"
                >
                  {item}
                </span>
              ))}
            </div>
          </div>
          <div className="mb-16"></div>
          <div></div>
        </div>
        <Footer></Footer>
      </div>
    </>
  );
}

export default Post31;
